@startuml

class House {
  + address : string
  + buildingMaterial : BuildingMaterial
}

class Basement {
  + name : string
  + size : float
}

class EarthBasement extends Basement {
  + humidityLevel : float
}

class ConcreteBasement extends Basement {}

class SemiDetachedHouse extends House {
  + hasGarden : boolean
  + numberOfWindows : int
}

class Carport {
  + isDoubleCarport : boolean
  + hasFlatRoof : boolean
}

class Garage {
  + hasAutomaticGarageDoor : boolean
}

class Company {
  + name : string
  + address : string
}

class JobLog {
  + hours : float
  + agreedPrice : double
}

enum BuildingMaterial {
  WOOD
  BRICK
  CONCRETE
}

House "0..1" *-- "0..1" Basement
SemiDetachedHouse "1" -- "2" Carport
SemiDetachedHouse "1" -- "0..1" Garage
House "1" -- "*" Company : serviced by
House "1" -- "*" JobLog
Company "1" -- "*" JobLog

@enduml

